/*
 * achievements.c
 *
 * Maps the game's Game Center achievements (inherited from the iOS version,
 * com.digitalgoldfish.bloons2.*) to Vita trophies.
 *
 * Trophy 0 is the platinum, which the system awards by itself once every
 * other trophy is unlocked. The order here must match TROPCONF.SFM in
 * extras/trophies (generated by extras/scripts/trophies/make_trophies.ps1).
 *
 * This software may be modified and distributed under the terms
 * of the GPLv3 license. See the LICENSE file for details.
 */

#include "game/achievements.h"

#include <string.h>

#include "utils/logger.h"
#include "utils/trophies.h"

typedef struct {
    const char *id;   // Game Center achievement ID suffix
    int trophy;
} AchievementMapping;

static const AchievementMapping mappings[] = {
    { "million_bloons",    1 },  // Million Pops     - Pop 100k Bloons.
    { "100_aces",          2 },  // Bloon Baron      - Launch 100 monkey aces.
    { "100_percent_level", 3 },  // 100%             - Pop every Bloon in a level.
    { "hit_nothing",       4 },  // Swing and a Miss - Hit nothing.
    { "complete_game",     5 },  // Ace Monkey       - Complete the game.
    { "use_super_monkey",  6 },  // Bloons of Steel  - Use a Super Monkey.
    { "use_solution",      7 },  // Bloon Academy    - Use a solution.
    { "25_menu_pops",      8 },  // Easter Egg       - Pop 25 Bloons in the main menu.
    { "50_planet_spins",   9 },  // Starfleet Bloon  - Spin the planet 50 times.
    { "zone_grass",       10 },  // Daisy Cutter     - You completed Popping Fields!
    { "zone_desert",      11 },  // Just Deserts     - You completed Bloon Dunes!
    { "zone_ice",         12 },  // Ice Demon        - You completed Frosty Fun!
    { "zone_mountains",   13 },  // My Everest       - You completed Sneak Peaks!
    { "zone_jungle",      14 },  // Jungle Fever     - You completed Rubber Jungle!
    { "zone_temple",      15 },  // Temple of Bloon  - You completed Temple of Bloon!
    { "zone_beach",       16 },  // Bloon BBQ        - You completed Crazy Coast!
    { "zone_volcano",     17 },  // Hot Stuff        - You completed Mount Magma!
};

void achievement_report(const char *id, float percent) {
    if (!id) return;

    l_info("achievement_report(\"%s\", %.1f)", id, percent);
    if (percent < 100.0f)
        return;

    // Accept both the full ID and just its last component
    const char *suffix = strrchr(id, '.');
    suffix = suffix ? suffix + 1 : id;

    for (size_t i = 0; i < sizeof(mappings) / sizeof(mappings[0]); i++) {
        if (strcmp(suffix, mappings[i].id) == 0) {
            trophies_unlock(mappings[i].trophy);
            return;
        }
    }

    l_warn("achievement_report: unknown achievement \"%s\"", id);
}
